import React from 'react';
import { Box, Spinner, Button, Tabs, TabList, Tab, TabPanels, TabPanel } from '@chakra-ui/react';
import { __ } from '@eventespresso/i18n';

import { BasicSettings, DateSettings, FormattingSettings, useCalendarSettings } from './index';
import { ThemeSettings } from './theme-settings/ThemeSettings';
import { Binoculars, CalendarDate, PaintBucket, Textarea } from '../icons/';

export const CalendarSettings: React.FunctionComponent = () => {
	const {
		categories,
		settings,
		loading,
		formatErrors,
		updateSettings,
		handleChange,
		handleInputChange,
		handleColorInputChange,
		handleSave,
		handleDateFormatChange,
		handleMonthFormatChange,
		handleTimeFormatChange,
		handleCustomFormatChange,
		handleCheckboxChange,
		handleLayoutAlgorithmChange,
		handleCategoryColor,
	} = useCalendarSettings();

	if (!settings) {
		return <Spinner thickness='4px' speed='0.65s' emptyColor='gray.200' color='blue.500' size='xl' m={8} />;
	}

	return (
		<Box p={5} fontSize='sm'>
			<Tabs align='start' orientation='vertical' variant='unstyled' minHeight='90vh'>
				<TabList>
					<Tab alignItems='flex-start' fontSize='sm'>
						<Binoculars size={24} />
						{__('Calendar Views')}
					</Tab>
					<Tab alignItems='flex-start' fontSize='sm'>
						<Textarea size={24} />
						{__('Text Labels')}
					</Tab>
					<Tab alignItems='flex-start' fontSize='sm'>
						<CalendarDate size={21} />
						{__('Date Formats')}
					</Tab>
					<Tab alignItems='flex-start' fontSize='sm'>
						<PaintBucket size={21} />
						{__('Colors & Styles')}
					</Tab>
				</TabList>
				<TabPanels>
					<TabPanel className='cp-tab__views'>
						<BasicSettings
							settings={settings}
							handleChange={handleChange}
							handleInputChange={handleInputChange}
							handleLayoutAlgorithmChange={handleLayoutAlgorithmChange}
						/>
					</TabPanel>
					<TabPanel className='cp-tab__labels'>
						<FormattingSettings settings={settings} handleInputChange={handleInputChange} />
					</TabPanel>
					<TabPanel className='cp-tab__formats'>
						<DateSettings
							settings={settings}
							formatErrors={formatErrors}
							handleDateFormatChange={handleDateFormatChange}
							handleMonthFormatChange={handleMonthFormatChange}
							handleTimeFormatChange={handleTimeFormatChange}
							handleCustomFormatChange={handleCustomFormatChange}
						/>
					</TabPanel>
					<TabPanel className='cp-tab__colors'>
						<ThemeSettings
							categories={categories}
							settings={settings}
							handleColorInputChange={handleColorInputChange}
							handleCheckboxChange={handleCheckboxChange}
							handleInputChange={handleInputChange}
							handleCategoryColor={handleCategoryColor}
							updateSettings={updateSettings}
						/>
					</TabPanel>
					<Button
						disabled={loading}
						className='cp-save-settings'
						colorScheme='blue'
						mx={0}
						my={4}
						onClick={handleSave}
					>
						{loading ? __('Saving…') : __('Save Settings')}
					</Button>
				</TabPanels>
			</Tabs>
		</Box>
	);
};
